bounded("A queue log line is depth= followed by a canonical integer from 0 through 63. No signs, spaces or other fields.","depth=",0,63,r"(?:[0-9]|[1-5][0-9]|6[0-3])")
C("An HTTP log summary is HTTP plus one space, status 400 through 499, one space and exactly GET or POST, uppercase. No path or other fields.",r"HTTP 4[0-9]{2} (?:GET|POST)","HTTP 400 GET|HTTP 499 POST|HTTP 404 GET|HTTP 403 POST|HTTP 401 GET|HTTP 405 POST|HTTP 450 GET|HTTP 498 POST","HTTP 399 GET|HTTP 500 POST|HTTP 40 GET|HTTP 4000 GET|HTTP 400 get|HTTP 400 PUT|HTTP 4a0 GET|HTTP 400  GET", "Status width and method alternatives are both restricted.")
C("A timestamped event is HH:MM:SS then one space and either WARN or ERROR. Padded 24-hour time: hour 00 to 23, minutes and seconds 00 to 59. No other fields.",r"(?:[01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9] (?:WARN|ERROR)","00:00:00 WARN|23:59:59 ERROR|12:30:45 WARN|01:01:01 ERROR|09:59:00 WARN|20:00:59 ERROR|22:45:10 WARN|10:10:10 ERROR","24:00:00 WARN|23:60:00 WARN|23:00:60 WARN|1:00:00 WARN|00:00:00 warn|00:00:00 INFO|00:00:00  WARN", "Every time component has its own range.")
C("A worker line is worker= plus a canonical integer 1 to 32, one space and state= followed by idle or busy, lowercase. Exact field order, no other text.",r"worker=(?:[1-9]|[12][0-9]|3[0-2]) state=(?:idle|busy)","worker=1 state=idle|worker=32 state=busy|worker=1 state=busy|worker=32 state=idle|worker=9 state=idle|worker=10 state=busy|worker=20 state=idle|worker=31 state=busy","worker=0 state=idle|worker=33 state=busy|worker=01 state=idle|worker=1 state=Idle|worker=1 state=dead|worker=1  state=idle|state=idle worker=1", "The state field is an exact enumeration.")
C("An access log message is path= followed by slash and 1 to 12 lowercase ASCII letters, one space and bytes= followed by a canonical integer 0 to 999. No additional path components or fields.",r"path=\/[a-z]{1,12} bytes=(?:0|[1-9][0-9]{0,2})","path=/a bytes=0|path=/abcdefghijkl bytes=999|path=/index bytes=1|path=/status bytes=99|path=/health bytes=100|path=/data bytes=10|path=/foo bytes=9|path=/bar bytes=500","path=/ bytes=0|path=/abcdefghijklm bytes=0|path=/A bytes=0|path=/a bytes=1000|path=/a bytes=00|path=/a  bytes=0|path=/a/b bytes=0", "Path length and canonical byte counter are independent.")
search("Search raw server output for a request number 1 through 64 immediately between lowercase req= and semicolon. Shortest ASCII decimal spelling; other output is unrestricted.","req=",r"(?:[1-9]|[1-5][0-9]|6[0-4])",["1","2","9","10","20","50","63","64"],";",["0","65","01","+1","a","1.0"])
search("Find an eight-character uppercase hexadecimal fault code immediately between lowercase fault[ and ]. Search anywhere in output.","fault[",r"[0-9A-F]{8}",["00000000","FFFFFFFF","ABCDEF12","12345678","DEADBEEF","A0000001","01234567","99AABBCC"],"]",["0000000","000000000","abcdef12","ABCDEFg1","A000000!","é0000000"])
C("Search LF-separated output for an entire line ERROR followed by colon, one space and 1 to 20 lowercase ASCII letters or spaces. At least one letter is required. Other lines may be arbitrary; CR is not a line delimiter.",r"(?:^|\n)ERROR: (?=[a-z ]{1,20}(?:\n|(?![\s\S])))[ ]*[a-z][a-z ]*(?=\n|(?![\s\S]))","ERROR: a|ERROR: abcdefghijklmnopqrst|x\nERROR: bad request\ny|\nERROR: fail\n|ERROR:  a|ERROR: a |ERROR:  bad |x\nERROR: broken","ERROR: |ERROR:  |ERROR: abcdefghijklmnopqrstu|ERROR: Fail|x ERROR: fail|ERROR: fail1|ERROR: fail\r|ERROR:\tfail", "Whole-line semantics and a nonblank body must both hold.",contains=True)
equal_pair("A correlation summary is corr: and two identical eight-character lowercase hexadecimal IDs separated by slash. Nothing else is allowed.","corr:","/",r"[0-9a-f]{8}",["00000000","ffffffff","abcdef12","12345678","deadbeef","a0000001","01234567","99aabbcc"])
C("A paired operation log is OPEN followed by one space and a lowercase ASCII operation name 3 to 8 letters, one LF, then CLOSE plus one space and the exact same name. No final LF, CR, messages or other lines.",r"OPEN ([a-z]{3,8})\nCLOSE \1","OPEN abc\nCLOSE abc|OPEN xyz\nCLOSE xyz|OPEN abcdefgh\nCLOSE abcdefgh|OPEN read\nCLOSE read|OPEN write\nCLOSE write|OPEN load\nCLOSE load|OPEN parse\nCLOSE parse|OPEN sample\nCLOSE sample","OPEN abc\nCLOSE xyz|OPEN ab\nCLOSE ab|OPEN abcdefghi\nCLOSE abcdefghi|OPEN ABC\nCLOSE ABC|OPEN abc\r\nCLOSE abc|OPEN abc CLOSE abc|OPEN  abc\nCLOSE abc", "The closing operation must agree exactly across the LF boundary.")
C("A localized log source is src= then 2 through 12 Unicode letters and literal ;ok. Count letter code points; no combining marks, spaces or digits.",r"src=\p{L}{2,12};ok","src=ab;ok|src=Été;ok|src=東京;ok|src=Δέλτα;ok|src=مرحبا;ok|src=Зима;ok|src=abcdefghijkl;ok|src=Aé;ok","src=a;ok|src=abcdefghijklm;ok|src=ab1;ok|src=a_b;ok|src=a b;ok|src=é;ok|src=😀a;ok|src=ab;OK", "The localized source and fixed suffix have different case rules.","u")
envelope("A diagnostic block is entirely enclosed in LOG{ and }LOG. Its interior is 1 through 40 Unicode code points, may include any characters and line breaks, and contains the lowercase substring error.","LOG{","}LOG","error")
line_copy("An LF-only log receipt has trace= followed by eight lowercase hexadecimal characters on line one, then copy= and the exact same trace on line two. No final LF or spaces.","trace=",r"[0-9a-f]{8}",["00000000","ffffffff","abcdef12","12345678","deadbeef","a0000001","01234567","99aabbcc"])
C("An allocation log is take= and a canonical integer 1 through 99, semicolon, release= and the exact same integer, semicolon, free= and an integer 0 through 99 that differs from the taken value. No spaces or other fields.",r"take=([1-9][0-9]?);release=\1;free=(?!\1$)(?:0|[1-9][0-9]?)","take=1;release=1;free=0|take=99;release=99;free=98|take=10;release=10;free=1|take=9;release=9;free=99|take=20;release=20;free=30|take=30;release=30;free=20|take=50;release=50;free=0|take=1;release=1;free=10","take=1;release=2;free=0|take=1;release=1;free=1|take=0;release=0;free=1|take=100;release=100;free=1|take=01;release=01;free=0|take=1;release=1;free=100|take=1;release=1;free=00", "The first equality and final inequality compare whole canonical values.")
C("A log transport marker is BEGIN, one ASCII space, a matching pair of single or double ASCII quotes around a lowercase ASCII label 3 to 8 letters, LF, then END plus one space and the same quote-label-quote spelling. The label cannot be tmp. No final LF.",r"BEGIN (['\"])(?!tmp\1)([a-z]{3,8})\1\nEND \1\2\1","BEGIN 'abc'\nEND 'abc'|BEGIN \"xyz\"\nEND \"xyz\"|BEGIN 'abcdefgh'\nEND 'abcdefgh'|BEGIN \"tmpx\"\nEND \"tmpx\"|BEGIN 'read'\nEND 'read'|BEGIN \"write\"\nEND \"write\"|BEGIN 'load'\nEND 'load'|BEGIN \"parse\"\nEND \"parse\"","BEGIN 'tmp'\nEND 'tmp'|BEGIN 'abc'\nEND 'xyz'|BEGIN 'abc'\nEND \"abc\"|BEGIN 'abc\"\nEND 'abc'|BEGIN 'ab'\nEND 'ab'|BEGIN 'abcdefghi'\nEND 'abcdefghi'|BEGIN 'abc'\r\nEND 'abc'", "Quote equality and label equality both survive the line break.")
